@app.post('/checkout')
def checkout(req):
    cart = db.query(Cart).get(req.cart_id)
    total = sum(i.price * i.qty for i in cart.items)
    if cart.user.tier == 'gold':
        total *= 0.9
    db.add(Payment(cart_id=cart.id, amount=total))
    db.commit()
    return {'total': total}
